-- =====================================================
-- Database Maintenance - Sparepart Master Data
-- Auto-generated dari Daftar_Sparepart_Gudang.xlsx
-- Import: buka phpMyAdmin > pilih database > tab SQL > paste file ini
-- =====================================================

CREATE DATABASE IF NOT EXISTS db_maintenance CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE db_maintenance;

-- ---------------------------------------------------
-- 1. TABEL MESIN
-- ---------------------------------------------------
CREATE TABLE IF NOT EXISTS mesin (
    id_mesin INT AUTO_INCREMENT PRIMARY KEY,
    nama_mesin VARCHAR(150) NOT NULL UNIQUE,
    keterangan VARCHAR(255) NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;

-- ---------------------------------------------------
-- 2. TABEL SPAREPART (master part, tidak terikat 1 mesin)
-- ---------------------------------------------------
CREATE TABLE IF NOT EXISTS sparepart (
    id_sparepart INT AUTO_INCREMENT PRIMARY KEY,
    part_number VARCHAR(150) NOT NULL UNIQUE,
    nama_part VARCHAR(255) NOT NULL,
    kategori VARCHAR(150) NULL,
    tingkat_kritikal ENUM('Tinggi','Sedang','Rendah') NOT NULL DEFAULT 'Sedang',
    satuan VARCHAR(20) DEFAULT 'pcs',
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;

-- ---------------------------------------------------
-- 3. TABEL RELASI MESIN <-> SPAREPART (many-to-many + info pemasangan)
-- ---------------------------------------------------
CREATE TABLE IF NOT EXISTS mesin_sparepart (
    id INT AUTO_INCREMENT PRIMARY KEY,
    id_mesin INT NOT NULL,
    id_sparepart INT NOT NULL,
    qty_terpasang INT DEFAULT 1,
    posisi_manual VARCHAR(150) NULL,
    dokumen_referensi VARCHAR(255) NULL,
    UNIQUE KEY uq_mesin_part (id_mesin, id_sparepart),
    CONSTRAINT fk_ms_mesin FOREIGN KEY (id_mesin) REFERENCES mesin(id_mesin) ON DELETE CASCADE,
    CONSTRAINT fk_ms_sparepart FOREIGN KEY (id_sparepart) REFERENCES sparepart(id_sparepart) ON DELETE CASCADE
) ENGINE=InnoDB;

-- ---------------------------------------------------
-- 4. TABEL STOK GUDANG (dipakai dashboard: stok saat ini vs stok minimum)
-- ---------------------------------------------------
CREATE TABLE IF NOT EXISTS stok_gudang (
    id_sparepart INT PRIMARY KEY,
    qty_stok INT NOT NULL DEFAULT 0,
    stok_minimum INT NOT NULL DEFAULT 1,
    lokasi_rak VARCHAR(50) NULL,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    CONSTRAINT fk_stok_sparepart FOREIGN KEY (id_sparepart) REFERENCES sparepart(id_sparepart) ON DELETE CASCADE
) ENGINE=InnoDB;

-- ---------------------------------------------------
-- 5. TABEL SUPPLIER (opsional, untuk pengembangan berikutnya)
-- ---------------------------------------------------
CREATE TABLE IF NOT EXISTS supplier (
    id_supplier INT AUTO_INCREMENT PRIMARY KEY,
    nama_supplier VARCHAR(150) NOT NULL,
    kontak VARCHAR(50) NULL,
    email VARCHAR(100) NULL,
    alamat VARCHAR(255) NULL
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS sparepart_supplier (
    id_sparepart INT NOT NULL,
    id_supplier INT NOT NULL,
    harga_satuan DECIMAL(15,2) NULL,
    lead_time_hari INT NULL,
    PRIMARY KEY (id_sparepart, id_supplier),
    CONSTRAINT fk_ss_sparepart FOREIGN KEY (id_sparepart) REFERENCES sparepart(id_sparepart) ON DELETE CASCADE,
    CONSTRAINT fk_ss_supplier FOREIGN KEY (id_supplier) REFERENCES supplier(id_supplier) ON DELETE CASCADE
) ENGINE=InnoDB;

-- ---------------------------------------------------
-- 6. TABEL RIWAYAT PEMAKAIAN (untuk histori maintenance, isi manual nanti)
-- ---------------------------------------------------
CREATE TABLE IF NOT EXISTS riwayat_pemakaian (
    id INT AUTO_INCREMENT PRIMARY KEY,
    id_mesin INT NOT NULL,
    id_sparepart INT NOT NULL,
    tanggal DATE NOT NULL,
    qty_terpakai INT NOT NULL DEFAULT 1,
    keterangan VARCHAR(255) NULL,
    CONSTRAINT fk_rp_mesin FOREIGN KEY (id_mesin) REFERENCES mesin(id_mesin) ON DELETE CASCADE,
    CONSTRAINT fk_rp_sparepart FOREIGN KEY (id_sparepart) REFERENCES sparepart(id_sparepart) ON DELETE CASCADE
) ENGINE=InnoDB;

-- ---------------------------------------------------
-- DATA: MESIN
-- ---------------------------------------------------
ON DUPLICATE KEY UPDATE nama_mesin=VALUES(nama_mesin);

